"""WKT parsing, axis detection, and geometry repair."""

import logging
from typing import Tuple, Optional
from shapely.geometry import shape, Point, Polygon, MultiPolygon
from shapely.wkt import loads as wkt_loads
from shapely.ops import unary_union
import json

import config

logger = logging.getLogger(__name__)


def parse_wkt(wkt_str: str):
    """Parse WKT string to Shapely geometry.

    Args:
        wkt_str: WKT or GeoJSON string

    Returns:
        Shapely geometry or None if parsing fails
    """
    if not wkt_str or pd.isna(wkt_str):
        return None

    try:
        # Try WKT first
        return wkt_loads(wkt_str)
    except Exception:
        pass

    try:
        # Try GeoJSON
        geom_dict = json.loads(wkt_str)
        return shape(geom_dict)
    except Exception:
        logger.warning(f"Could not parse geometry: {wkt_str[:100]}")
        return None


def is_in_brazil(lon: float, lat: float) -> bool:
    """Check if coordinate is within Brazil's bounding box."""
    return (config.BRAZIL_LON_MIN < lon < config.BRAZIL_LON_MAX and
            config.BRAZIL_LAT_MIN < lat < config.BRAZIL_LAT_MAX)


def detect_axis_order(geom) -> Tuple[bool, Optional]:
    """Detect if geometry has swapped lat/lon axes.

    Returns:
        (needs_repair, repaired_geometry or None)
    """
    if geom is None:
        return False, None

    try:
        # Extract coordinates
        if geom.geom_type == 'Point':
            coords = [(geom.x, geom.y)]
        elif geom.geom_type == 'Polygon':
            coords = list(geom.exterior.coords)
        elif geom.geom_type in ['LineString', 'MultiPoint']:
            coords = list(geom.coords)
        else:
            return False, None

        # Check coordinate validity
        lons = [c[0] for c in coords]
        lats = [c[1] for c in coords]

        in_brazil_normal = all(is_in_brazil(lon, lat) for lon, lat in coords)
        in_brazil_flipped = all(is_in_brazil(lat, lon) for lon, lat in coords)

        if in_brazil_normal:
            return False, None  # No repair needed

        if in_brazil_flipped and not in_brazil_normal:
            # Swap coordinates
            swapped = [(lat, lon) for lon, lat in coords]
            if geom.geom_type == 'Point':
                return True, Point(swapped[0])
            elif geom.geom_type == 'Polygon':
                return True, Polygon(swapped)
            elif geom.geom_type == 'LineString':
                return True, LineString(swapped)

        return False, None  # Neither works
    except Exception as e:
        logger.warning(f"Error detecting axis order: {e}")
        return False, None


def repair_geometry(geom):
    """Repair invalid geometry (make_valid + buffer(0)).

    Args:
        geom: Shapely geometry

    Returns:
        Repaired geometry or None if repair fails
    """
    if geom is None:
        return None

    try:
        if not geom.is_valid:
            # Try make_valid
            geom = geom.buffer(0)

        if geom.is_empty:
            return None

        return geom
    except Exception as e:
        logger.warning(f"Error repairing geometry: {e}")
        return None


def normalize_geometry(geom_str: str) -> Tuple[Optional, str]:
    """Normalize geometry from WKT: parse, detect axis order, repair.

    Returns:
        (geometry, status)
    """
    if not geom_str or pd.isna(geom_str):
        return None, 'empty'

    # Parse WKT
    geom = parse_wkt(geom_str)
    if geom is None:
        return None, 'parse_failed'

    # Detect and repair axis order
    needs_repair, repaired = detect_axis_order(geom)
    if needs_repair:
        geom = repaired
        status = 'axis_repaired'
    else:
        status = 'ok'

    # Repair invalid geometry
    geom = repair_geometry(geom)
    if geom is None:
        return None, 'repair_failed'

    return geom, status


