def round_numeric_columns(df, schema_key: str) -> pd.DataFrame:
    """Round numeric columns according to precision spec.

    Args:
        df: DataFrame
        schema_key: e.g. 'q01', 'q30'

    Returns:
        DataFrame with rounded numeric columns
    """
    if schema_key not in QUESTION_SCHEMA:
        return df

    precision = QUESTION_SCHEMA[schema_key].get('precision', {})
    for col, decimals in precision.items():
        if col in df.columns:
            df[col] = df[col].round(decimals)

    return df

